mkdir -p /app/tests && cat > /app/tests/helpers.py <<'EOF'
import zlib, struct

def crc32(b): return zlib.crc32(b) & 0xffffffff

def rec(seq, kind, txid, payload=b'', crc=None, plen=None, header=None):
    """Build a record. header lets you corrupt raw header fields."""
    if header is None:
        header = struct.pack('<IIBI', len(payload) if plen is None else plen, seq, kind, txid)
    body = header + payload
    c = crc32(body) if crc is None else crc
    return body + struct.pack('<I', c)

def patch_payload(page, off, data):
    return struct.pack('<HHH', page, off, len(data)) + data

def commit_payload(count, digest):
    return struct.pack('<II', count, digest)

def digest_of(*payloads):
    return crc32(b''.join(payloads))
EOF
